/**
 * Reserved paragraph ids (reportsthatmatter-efso, decision 0012): where each published id was first
 * served, so a re-render keeps it on that paragraph and suffixes a new paragraph that asks for it.
 *
 * `reports/<id>/reserved-ids.txt`, generated by `pnpm aliases generate` (and `seed-reserved` from
 * history), never hand-edited. Grouped by when the id was first recorded and the section it was in:
 *
 *   ## 2026-11-12T19:04:11Z 2-climate-change-our-approach
 *   key-messages 1a2b3c4d 9f8e7d6c
 *
 * (`<id> <fingerprint of its text> <fingerprint of the next passage's text>`; `-` for none.)
 * Each id appears once, at its first publication; a later render never rewrites it, because the
 * first meaning is the one a link was made with. `renderArtifacts(markdown, { reserved })` (ingest
 * >= v0.37.0) does the matching; this file only stores, orders and loads the list.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "yaml";
import { followAlias } from "./aliases";

export type ReservedEntry = { id: string; section: string; fingerprint: string; next: string; since: string };
/** What `renderArtifacts`' `reserved` option takes (ingest's `ReservedId`). */
export type Reserved = { id: string; section: string; fingerprint?: string; next?: string };

const HEADER =
  "# Generated by `pnpm aliases generate` (reportsthatmatter-efso, decision 0012); do not edit by hand.\n" +
  "# Where each published paragraph id was first served: `## <first recorded> <section>`, then `<id> <text fingerprint> <next passage's fingerprint>`.\n" +
  "# The renderer keeps each id on that paragraph and suffixes a new paragraph whose text asks for it.\n";

export function parseReserved(text: string): ReservedEntry[] {
  const out: ReservedEntry[] = [];
  let since = "";
  let section = "";
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line || (line.startsWith("#") && !line.startsWith("## "))) continue;
    if (line.startsWith("## ")) {
      [since, section] = line.slice(3).split(/\s+/);
      continue;
    }
    const [id, fingerprint, next = "-"] = line.split(/\s+/);
    out.push({ id, section, fingerprint, next: next === "-" ? "" : next, since });
  }
  return out;
}

export function formatReserved(entries: Iterable<ReservedEntry>): string {
  const groups = new Map<string, Map<string, string>>();
  for (const e of entries) {
    const key = `${e.since} ${e.section}`;
    if (!groups.has(key)) groups.set(key, new Map());
    groups.get(key)!.set(e.id, `${e.fingerprint} ${e.next || "-"}`);
  }
  let out = HEADER;
  for (const key of [...groups.keys()].sort()) {
    out += `## ${key}\n`;
    for (const [id, fp] of [...groups.get(key)!].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) out += `${id} ${fp}\n`;
  }
  return out;
}

/** Adds each entry whose id is not recorded yet; an id already there keeps its first record. */
export function addReserved(base: Iterable<ReservedEntry>, more: Iterable<ReservedEntry>): ReservedEntry[] {
  const byId = new Map<string, ReservedEntry>();
  for (const e of base) if (!byId.has(e.id)) byId.set(e.id, e);
  for (const e of more) if (!byId.has(e.id)) byId.set(e.id, e);
  return [...byId.values()];
}

/**
 * Within one family the de-duplicator hands out `base`, `base-2`, … `base-10` in reading order, so the shorter id, then
 * the lower one, came first. Not the trailing number: a text that itself ends in a number (`…-section-19`,
 * `…-offense-i-5`, `…-may-2022`) would sort after its own `-2` and swap two identical paragraphs (review 2026-11-13).
 */
const familyOrder = (a: string, b: string) => a.length - b.length || (a < b ? -1 : a > b ? 1 : 0);

/**
 * The renderer's list: oldest first (the meaning a link was made with wins a contested paragraph), then the lower
 * suffix (`familyOrder`). A section slug a later render renamed is followed through `aliases.yaml`'s `sections`.
 */
export function toReserved(entries: readonly ReservedEntry[], sectionAliases: Record<string, string> = {}): Reserved[] {
  return [...entries]
    .sort((a, b) => (a.since !== b.since ? (a.since < b.since ? -1 : 1) : familyOrder(a.id, b.id)))
    .map((e) => ({
      id: e.id,
      section: Object.hasOwn(sectionAliases, e.section) ? (followAlias(sectionAliases, e.section, (s) => !Object.hasOwn(sectionAliases, s)) ?? e.section) : e.section,
      fingerprint: e.fingerprint,
      next: e.next,
    }));
}

export const reservedPath = (root: string, id: string) => join(root, `reports/${id}/reserved-ids.txt`);

export function loadReservedEntries(root: string, id: string): ReservedEntry[] {
  const path = reservedPath(root, id);
  return existsSync(path) ? parseReserved(readFileSync(path, "utf8")) : [];
}

/** The `reserved` option for rendering report `id` from this checkout: its reserved-ids.txt, sections followed through its aliases.yaml. */
export function loadReserved(root: string, id: string): Reserved[] {
  const entries = loadReservedEntries(root, id);
  if (!entries.length) return [];
  const aliasPath = join(root, `reports/${id}/aliases.yaml`);
  const sections = existsSync(aliasPath) ? ((parse(readFileSync(aliasPath, "utf8")) ?? {}).sections ?? {}) : {};
  return toReserved(entries, sections);
}
